const puppeteer = require('puppeteer-core');
(async () => {
  const browser = await puppeteer.launch({
    executablePath: '/Applications/Google Chrome.app/Contents/MacOS/Google Chrome',
    headless: 'new', args: ['--no-sandbox','--disable-gpu']
  });
  const page = await browser.newPage();
  await page.setViewport({width:1024, height:780});
  page.on('console', m => { if(m.type()==='error') console.log('PAGE ERROR:', m.text()); });
  page.on('pageerror', e => console.log('PAGE EXCEPTION:', e.message));
  await page.goto('file:///Users/lisun/workplace/go-harness/web/sessions/session-38/workspace/sleep-calendar.html', {waitUntil:'networkidle0', timeout:15000});
  await new Promise(r=>setTimeout(r,400));

  const gridTransform = ()=> page.evaluate(()=>{
    const g=document.querySelector('#stage svg g');
    return g?g.getAttribute('transform'):null;
  });
  const cellCount = ()=> page.evaluate(()=>document.querySelectorAll('#stage .cell').length);
  const tipVisible=()=> page.evaluate(()=>document.getElementById('tip').style.opacity);

  console.log('开局 cell 数:', await cellCount());
  console.log('开局 transform:', await gridTransform());

  // 模拟拖拽：mouse down on stage, move left+down, up
  const stage=await page.$('#stage');
  const box=await stage.boundingBox();
  await page.mouse.move(box.x+400, box.y+200);
  await page.mouse.down();
  await page.mouse.move(box.x+180, box.y+340, {steps:15});
  await page.mouse.up();
  console.log('拖拽后 transform:', await gridTransform());

  // 悬停一个格子，看 tooltip 是否出现
  await page.evaluate(()=>{
    const c=document.querySelector('#stage .cell');
    const r=c.getBoundingClientRect();
    // dispatch mouseenter+mousemove via d3? 直接调用 cell 的 mousemove 事件
    c.dispatchEvent(new MouseEvent('mousemove',{bubbles:true,clientX:r.x+10,clientY:r.y+10}));
  });
  await new Promise(r=>setTimeout(r,150));
  console.log('悬停后 tooltip 内容:', await page.evaluate(()=>document.getElementById('tip').innerHTML,"").catch(()=>'none'));

  // 切换指标
  await page.select('#metric','quality');
  await new Promise(r=>setTimeout(r,120));
  console.log('切到质量后首格 fill:', await page.evaluate(()=>document.querySelector('#stage .cell').getAttribute('fill')));

  // 点击"显示全部"
  await page.click('#fit');
  await new Promise(r=>setTimeout(r,550));
  console.log('显示全部后 transform:', await gridTransform());

  // 点击"回到今天"
  await page.click('#today');
  await new Promise(r=>setTimeout(r,550));
  console.log('回到今天后 transform:', await gridTransform());

  await browser.close();
  console.log('DONE');
})().catch(e=>{console.log('FATAL:', e.message); process.exit(1);});
